INSERT INTO `ai_prompt_template` VALUES (2070000000000000101,'platform',NULL,'test_flow_design','从零搭建','新建 test_flow，画布为空或仅有 start 节点','为本测试流从零搭建「{流程名称}」：\n1. {步骤 1 业务描述}\n2. {步骤 2 业务描述}\n3. {步骤 3 业务描述}\n\n要求：\n- 需要登录态的多步流程，第一步开启会话保持（useRunSession）\n- 关键步骤后校验 {期望结果}\n- 需要从响应提取：{变量名及用途，如 token 供后续鉴权}\n- 线性串联即可，暂不加分支',1,1,101,'从零搭建',0,'2026-07-04 21:37:19',NULL),(2070000000000000102,'platform',NULL,'test_flow_design','带子流/外联搭建','登录子流或外联环境变量','搭建「{流程名称}」：\n- 登录：使用项目接口「{登录接口业务名}」，extract token 到 flow\n- 后续业务：{描述}\n- OAuth / 验证码等：优先用平台子流模板；若无则外联 {{env.*}} 环境变量',1,1,102,'从零搭建',0,'2026-07-04 21:37:19',NULL),(2070000000000000201,'platform',NULL,'test_flow_design','末尾追加步骤','画布已有节点，在末尾追加','在当前测试流末尾追加：\n{新业务步骤描述}\n\n不要删除或修改现有节点，除非与 {某冲突点} 冲突。\n新增节点与现有最后一步 HTTP 之间用 assert 校验 {期望状态}。',1,1,201,'扩展现有流',0,'2026-07-04 21:37:19',NULL),(2070000000000000202,'platform',NULL,'test_flow_design','插入中间步骤','在两节点之间插入新步骤','在 @{Node:某HTTP节点} 与 @{Node:下一节点} 之间插入：\n{新步骤描述}\n\n后续节点若依赖旧 extract 变量，请同步 update 占位符引用。',1,1,202,'扩展现有流',0,'2026-07-04 21:37:19',NULL),(2070000000000000301,'platform',NULL,'test_flow_design','复制/变异场景','同一流程测多种业务分支','基于当前主流拓扑，新增运行场景「{场景名}」：\n- 环境：{环境名或 testProjectEnvId}\n- flowSeed 初值：{键名=值，如 loginMobile=13800000002}\n- 默认场景保持不变\n\n并在 scenarioPatch 中 addScenarios；HTTP 节点用 {{flow.*}} 引用 seed，不要写死账号。',1,1,301,'运行场景',0,'2026-07-04 21:37:19',NULL),(2070000000000000401,'platform',NULL,'test_flow_design','API 变更-参数/路径','IDEA 同步后修复单接口','项目 API「{apiName}」已更新，变更如下：\n- {变更点 1，如 path /api/login → /api/v2/auth/login}\n- {变更点 2，如 请求体 password → credential}\n\n请扫描本测试流，仅修复引用该 API 的 HTTP 节点及相关 assert/extract，\n不要改动无关节点和场景配置。',1,1,401,'API 变更修复',0,'2026-07-04 21:37:19',NULL),(2070000000000000402,'platform',NULL,'test_flow_design','API 变更-响应结构','响应 JSONPath 变更','接口「{apiName}」响应 JSON 已变：{旧 JSONPath} → {新 JSONPath}。\n请更新所有相关节点的 extracts 和 assertRules；\nrequestConfig 若无变化则不要修改。',1,1,402,'API 变更修复',0,'2026-07-04 21:37:19',NULL),(2070000000000000403,'platform',NULL,'test_flow_design','API 变更-批量','多接口同步更新','以下接口已在 IDEA 同步更新：{apiName1}、{apiName2}、{apiName3}。\n请仅提交最小改动，优先 updateNode，避免 deleteNode 除非接口已删除。',1,1,403,'API 变更修复',0,'2026-07-04 21:37:19',NULL),(2070000000000000404,'platform',NULL,'test_flow_design','重置为 API 资产','清空历史复制的 requestConfig','以下 HTTP 节点 @{Node:…} 的 requestConfig 仅为历史复制，无业务定制：\n请清空 requestConfig 与 apiPath 覆盖，仅保留接口绑定与 extracts/asserts。',1,1,404,'API 变更修复',0,'2026-07-04 21:37:19',NULL),(2070000000000000501,'platform',NULL,'test_flow_design','Run 失败修复','结合 @Run 与 @Node 分析','@{Run:最近一次失败Run} 在 @{Node:失败节点名} 失败。\n请分析是请求参数、断言还是 extract 问题并修复。\n不要改动与本次失败无关的节点。',1,1,501,'Run 失败修复',0,'2026-07-04 21:37:19',NULL),(2070000000000000502,'platform',NULL,'test_flow_design','Run 失败修复（无@Run）','按步骤名定位失败','上次运行在本测试流失败，步骤名「{nodeName}」。\n请定位原因并修复相关 HTTP / assert 节点。',1,1,502,'Run 失败修复',0,'2026-07-04 21:37:19',NULL),(2070000000000000503,'platform',NULL,'test_flow_design','断言过严/过松','按实际业务调整断言','@{Run:…} 中 @{Node:…} 断言失败，但实际业务 {接受/拒绝} 是符合预期的。\n请根据失败 Run 的响应体，将断言调整为 {期望语义}，不要改 HTTP 请求参数。',1,1,503,'Run 失败修复',0,'2026-07-04 21:37:19',NULL),(2070000000000000601,'platform',NULL,'test_flow_design','插入登录子流','引用平台/项目子流','在本流开头插入登录子流「{模板名}」：\n- inputs：{name=value}\n- outputs：token → flow.{flowKey}\n\n主流程后续 HTTP 使用 {{flow.{flowKey}}} 鉴权。',1,1,601,'子流编排',0,'2026-07-04 21:37:19',NULL),(2070000000000000602,'platform',NULL,'test_flow_design','抽取子流','将节点链重构为子流','将 @{Node:A} 到 @{Node:B} 之间的节点抽成可复用子流「{子流名}」：\n1. 说明建议的 inputs/outputs 映射\n2. 主流程用 subflow 节点替换原节点链\n3. 不要改变对外 flow 变量名（或列出 rename 对照）',1,1,602,'子流编排',0,'2026-07-04 21:37:19',NULL),(2070000000000000701,'platform',NULL,'test_flow_design','新增运行场景','仅调整场景配置','为本测试流配置运行场景：\n- 新增场景「{场景名}」，绑定环境「{环境名}」\n- flowSeed：{键=值}\n- 设为默认运行场景\n\n不要修改 graph 节点，仅调整场景配置。',1,1,701,'运行场景',0,'2026-07-04 21:37:19',NULL),(2070000000000000702,'platform',NULL,'test_flow_design','检查场景配置','修正环境绑定与 flowSeed','检查当前所有场景的环境绑定与 flowSeed 是否合理；\n若有场景仍指向 {错误环境名}，请修正。',1,1,702,'运行场景',0,'2026-07-04 21:37:19',NULL),(2070000000000000801,'platform',NULL,'test_flow_design','加强断言','为 HTTP 及下游补 assert','为 @{Node:某HTTP} 及其下游补充 assert：\n- HTTP 状态码 2xx\n- 响应体 {业务字段} 符合 {条件}\n- 若已有 assert 节点，update 而非重复 add',1,1,801,'断言与变量',0,'2026-07-04 21:37:19',NULL),(2070000000000000802,'platform',NULL,'test_flow_design','补 extract','从响应提取 flow 变量','@{Node:某HTTP} 响应中需要提取 {变量名} 供后续使用，JSONPath {路径}，scope=flow。\n请 updateNode 添加 extracts，并检查下游节点占位符是否引用 {{flow.{变量名}}}。',1,1,802,'断言与变量',0,'2026-07-04 21:37:19',NULL),(2070000000000000803,'platform',NULL,'test_flow_design','补 condition 分支','按响应字段分支','在 @{Node:某HTTP} 之后按响应 {字段} 分支：\n- 等于 {值 A} → {目标步骤/节点语义}\n- 否则 → {另一路径}',1,1,803,'断言与变量',0,'2026-07-04 21:37:19',NULL),(2070000000000000901,'platform',NULL,'test_flow_design','重构整理','不改变业务语义整理拓扑','当前测试流拓扑较乱，请在不改变业务语义的前提下：\n- 合并重复 HTTP 调用\n- 统一节点命名\n- 删除明显冗余的断言\n不要 delete 仍在用的节点。',1,1,901,'重构整理',0,'2026-07-04 21:37:19',NULL),(2070000000000000902,'platform',NULL,'test_flow_design','外联改绑定 API','将外联 HTTP 改为项目接口','将所有外联 HTTP 改为绑定项目已登记接口（若存在对应 API）。',1,1,902,'重构整理',0,'2026-07-04 21:37:19',NULL),(2070000000000001001,'platform',NULL,'test_flow_design','仅答疑-流程说明','只读分析，不改图','说明当前测试流的主路径、关键 flow 变量和运行场景配置。本次仅解释，不要改图。',1,1,1001,'仅答疑',0,'2026-07-04 21:37:19',NULL),(2070000000000001002,'platform',NULL,'test_flow_design','仅答疑-接口引用','分析 Api 在流中的使用','@{Api:某接口} 在本测试流中被哪些节点引用？各节点主要传什么参数？只读分析，不要改图。',1,1,1002,'仅答疑',0,'2026-07-04 21:37:19',NULL),(2070000000000002101,'platform',NULL,'test_api_design','补手机号约束','string + pattern / maxLength','为当前接口 Query/Path/Body 中的 mobile（或手机号字段）补结构约束：\n- type=string\n- pattern 匹配国内 11 位手机号\n- maxLength=11\n- 可附带 description\n\n禁止 enum/const。请调用工具后提交 patch，不要自动保存。',1,1,101,'补约束',0,'2026-07-22 13:51:11',NULL),(2070000000000002102,'platform',NULL,'test_api_design','补必填与区间约束','required / min max','根据接口语义，为关键必填参数补 required；数值参数补合理 minValue/maxValue（schema 用 minimum/maximum）。\n改 type 时清理不兼容约束。禁止 enum/const。提交 patch，不落库。',1,1,102,'补约束',0,'2026-07-22 13:51:11',NULL),(2070000000000002103,'platform',NULL,'test_api_design','测值用素材占位符','{{asset.*}} 默认测值','为当前接口缺少默认测值的参数补测值：\n- 优先 list_asset_variables 选用 {{asset.key.field}}\n- 环境相关用 {{env.*}}\n- 禁止写死密码、Token、密钥\n\n仅改测值层，不要把约束写进 testValue。提交 patch。',1,1,201,'补测值与变量',0,'2026-07-22 13:51:11',NULL),(2070000000000002104,'platform',NULL,'test_api_design','HMAC 签名前置脚本','动态签名 Header','为当前接口生成前置脚本：\n- 使用环境变量 signSecret（api.environment.get(\'signSecret\')）\n- 对请求体原文做 HMAC-SHA256，结果写入 Header X-Sign\n- 同时添加 X-Timestamp（当前毫秒时间戳）\n\n仅改前置脚本（script:pre）。',1,1,301,'写前置/后置脚本',0,'2026-07-22 13:51:11',NULL),(2070000000000002105,'platform',NULL,'test_api_design','状态码与业务码断言','api.test 后置断言','为当前接口生成后置断言：\n- HTTP 状态码 2xx\n- 响应 JSON 中 code 等于 0\n- 使用 api.test 块\n\n仅改后置脚本（script:post）。',1,1,302,'写前置/后置脚本',0,'2026-07-22 13:51:11',NULL),(2070000000000002106,'platform',NULL,'test_api_design','提取 token 变量','JSON 提取到 variables','从响应 JSON 提取 accessToken 到 api.variables（键名 token）。\n路径：$.data.accessToken\n\n仅改后置脚本。',1,1,303,'写前置/后置脚本',0,'2026-07-22 13:51:11',NULL),(2070000000000002107,'platform',NULL,'test_api_design','辅助请求获取 Token','sendRequest 获取 token','前置脚本先调用辅助接口获取 token：\n- POST 路径 /api/auth/token（baseUrl 用 api.environment.get(\'baseUrl\')）\n- 成功后将 token 写入 api.variables，并添加 Authorization Header\n\n仅改前置脚本。',1,1,304,'写前置/后置脚本',0,'2026-07-22 13:51:11',NULL),(2070000000000002108,'platform',NULL,'test_api_design','补接口说明','apiDescription','根据当前接口 method/path/参数摘要，撰写简洁的 apiDescription（中文，一两段），说明用途与关键入参/出参。\n提交 meta:apiDescription patch，不改脚本与约束。',1,1,401,'补接口说明',0,'2026-07-22 13:51:11',NULL),(2070000000000002109,'platform',NULL,'test_api_design','修复脚本执行失败','根据错误日志修复','上次调试脚本失败，错误信息：\n{粘贴错误日志}\n\n请根据当前脚本与接口参数摘要修复，仅改出问题的阶段。',1,1,402,'写前置/后置脚本',0,'2026-07-22 13:51:11',NULL),(2070000000000002110,'platform',NULL,'test_api_design','仅答疑不改配置','解释结构/脚本，不提交 patch','解释当前接口参数、约束、测值或前置/后置脚本在做什么。本次仅说明，不要调用 submit_api_design_patch。',1,1,501,'答疑',0,'2026-07-22 13:51:11',NULL);
/*!40000 ALTER TABLE `ai_prompt_template` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `gen_table`
--

DROP TABLE IF EXISTS `gen_table`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gen_table` (
  `table_id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `table_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '表名称',
  `table_comment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '表描述',
  `sub_table_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联子表的表名',
  `sub_table_fk_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '子表关联的外键名',
  `class_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '实体类名称',
  `tpl_category` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'crud' COMMENT '使用的模板（crud单表操作 tree树表操作）',
  `tpl_web_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '前端模板类型（element-ui模版 element-plus模版）',
  `package_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成包路径',
  `module_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成模块名',
  `business_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成业务名',
  `function_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成功能名',
  `function_author` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '生成功能作者',
  `gen_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '生成代码方式（0zip压缩包 1自定义路径）',
  `gen_path` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '/' COMMENT '生成路径（不填默认项目路径）',
  `options` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '其它生成选项',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`table_id`)
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='代码生成业务表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `gen_table`
--

LOCK TABLES `gen_table` WRITE;
/*!40000 ALTER TABLE `gen_table` DISABLE KEYS */;
INSERT INTO `gen_table` VALUES (11,'test_project','测试项目',NULL,NULL,'TestProject','crud','element-plus','com.qualitest.project','project','testProject','测试项目','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-02-05 17:19:15','','2026-02-05 19:17:28',NULL),(12,'test_project_api','测试项目API',NULL,NULL,'TestProjectApi','crud','element-plus','com.qualitest.project','project','testProjectApi','测试项目API','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-02-05 17:19:15','','2026-02-05 19:17:49',NULL),(13,'test_project_api_group','测试项目API分组',NULL,NULL,'TestProjectApiGroup','crud','element-plus','com.qualitest.project','project','testProjectApiGroup','测试项目API分组','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-02-05 17:19:16','','2026-02-05 19:18:39',NULL),(14,'test_project_env','测试项目环境',NULL,NULL,'TestProjectEnv','crud','element-plus','com.qualitest.project','project','testProjectEnv','测试项目环境','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-02-05 17:19:16','','2026-02-05 19:18:02',NULL),(15,'test_project_user_setting','测试项目用户设置',NULL,NULL,'TestProjectUserSetting','crud','element-plus','com.qualitest.project','project','testProjectUserSetting','测试项目用户设置','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-02-09 15:44:42','','2026-02-09 15:45:03',NULL),(16,'test_project_asset','测试项目素材库',NULL,NULL,'TestProjectAsset','crud','element-plus','com.qualitest.project','project','testProjectAsset','测试项目素材库','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-05-23 20:49:57','','2026-05-23 20:50:50',NULL),(17,'test_flow','测试流',NULL,NULL,'TestFlow','crud','element-plus','com.qualitest.project','project','testFlow','测试流','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-06-05 13:58:34','','2026-06-05 14:04:21',NULL),(18,'test_flow_run','测试流运行',NULL,NULL,'TestFlowRun','crud','element-plus','com.qualitest.project','project','testFlowRun','测试流运行','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-06-05 13:58:34','','2026-06-05 14:02:41',NULL),(19,'test_flow_run_step','测试流运行步骤',NULL,NULL,'TestFlowRunStep','crud','element-plus','com.qualitest.project','project','testFlowRunStep','测试流运行步骤','qualitest','0','/','{\"parentMenuId\":2000}','admin','2026-06-05 13:58:34','','2026-06-05 14:01:01',NULL);
